const claudeResp = $input.first().json;
const trade      = $('Check If New Trade').first().json;
const rawTagline = claudeResp?.content?.[0]?.text?.trim() || 'Trade like an insider.';
const tagline    = rawTagline.replace(/^["'\u201C\u201D\u2018\u2019]|["'\u201C\u201D\u2018\u2019]$/g, '').trim();
return [{ json: { ...trade, tagline } }];

const imageData = $input.first().json;
const trade     = $('Merge Tagline').first().json;
return [{ json: { ...trade, imageUrl: imageData.imageUrl } }];

const container = $input.first().json;
const trade     = $('Merge Image URL').first().json;
return [{ json: { ...trade, containerId: container.id } }];

const staticData = $getWorkflowStaticData('global');
const trade      = $('Save Container ID').first().json;
staticData.lastStoryTradeId = String(trade.id);
return [{ json: { success: true, postedTradeId: trade.id, igStoryId: $input.first().json.id } }];
